import React,{useEffect,useMemo,useRef,useState} from 'react';
import {ArrowRightLeft,BedDouble,CalendarPlus,CheckCircle2,ClipboardCheck,LogIn,LogOut,RefreshCw,Search,ShieldAlert,UserPlus,WalletCards} from 'lucide-react';
import {allowed,type BusinessRecord,type WebSession} from './session';
import {BlockerCard,BusyButton,Dialog,FormField} from '../../design-system/controls';
