type CommandFn=(operation:string,collection:string,id:string,payload:Record<string,unknown>)=>Promise<CommandOutcome>;
const field='w-full rounded-xl border border-slate-700 bg-slate-950 px-3 py-2.5 text-sm text-white outline-none focus:border-amber-400';
const button='rounded-xl border border-slate-700 bg-slate-900 px-3 py-2 text-sm font-semibold text-slate-200 hover:bg-slate-800 disabled:opacity-40';
const primary='rounded-xl bg-amber-400 px-4 py-2.5 text-sm font-bold text-slate-950 hover:bg-amber-300 disabled:opacity-40';
const active=(records:BusinessRecord[],collection:string)=>records.filter(record=>record.collection===collection&&!record.archived);
const data=(record?:BusinessRecord)=>record?.data as Record<string,any>|undefined;
const name=(record?:BusinessRecord)=>String(data(record)?.name||data(record)?.number||'Not available');
const money=(minor:unknown)=>new Intl.NumberFormat('en-KE',{style:'currency',currency:'KES'}).format(Number(minor||0)/100);
const date=(value:unknown,timeZone='Africa/Nairobi')=>value?new Intl.DateTimeFormat('en-KE',{timeZone,dateStyle:'medium',timeStyle:'short'}).format(new Date(String(value))):'—';
const outcomeMessage=(outcome:CommandOutcome,action='Action')=>{switch(outcome.kind){case'CONFIRMED':return `${action} confirmed and synchronized.`;case'DRAFT_SAVED':return `${action} saved as a draft; it has not taken effect.`;case'PENDING':return `${action} is waiting to synchronize. Do not submit it again.`;case'OUTCOME_UNKNOWN':case'REJECTED':case'CONFLICT':case'BLOCKED':return outcome.message}};

export function WebFrontDeskView({records,session,disabled,command,deviceId,queue=[],onActivity,onOpenGuestAccount}:{records:BusinessRecord[];session:WebSession;disabled:boolean;command:CommandFn;deviceId:string;queue?:QueuedCommand[];onActivity?:()=>void;onOpenGuestAccount?:(id:string)=>void}){
 const reservations=active(records,'roomReservations');const rooms=active(records,'rooms');const customers=active(records,'customers');const stays=active(records,'stays');const folios=active(records,'folios');const folioEntries=active(records,'folioEntries');const rates=active(records,'ratePlans');const blocks=active(records,'roomBlocks');
 const propertyTimeZone=String(session.propertyContext?.timeZone||data(active(records,'property')[0])?.timezone||'Africa/Nairobi');
 const [quickMode,setQuickMode]=useState<'RESERVE'|'WALK_IN'>('RESERVE');const [checkInId,setCheckInId]=useState('');const [query,setQuery]=useState('');const [moveId,setMoveId]=useState('');const [destination,setDestination]=useState('');const [reason,setReason]=useState('');const [notice,setNotice]=useState('');const [quickReservation,setQuickReservation]=useState(false);const [moveBusy,setMoveBusy]=useState(false);
 const guest=(id:string)=>name(customers.find(record=>record.id===id));const room=(id:string)=>name(rooms.find(record=>record.id===id));
 const filtered=useMemo(()=>reservations.filter(record=>{const value=query.trim().toLowerCase();if(!value)return true;return `${guest(String(data(record)?.customerId))} ${room(String(data(record)?.roomId))} ${record.id}`.toLowerCase().includes(value)}),[reservations,customers,rooms,query]);
 const arrivals=filtered.filter(record=>data(record)?.status==='RESERVED');const departures=filtered.filter(record=>data(record)?.status==='CHECKED_IN');
 const run=async(operation:string,collection:string,id:string,payload:Record<string,unknown>):Promise<CommandOutcome>=>{setNotice('');try{const outcome=await command(operation,collection,id,payload);setNotice(outcomeMessage(outcome,'Front Desk action'));return outcome}catch{const blocked:CommandOutcome={kind:'BLOCKED',message:'The Front Desk action could not be confirmed. Refresh Activity and verify it before retrying.'};setNotice(blocked.message);return blocked}};
 const checkIn=(record:BusinessRecord)=>setCheckInId(record.id);
 const checkoutBlocker=(record:BusinessRecord)=>{const stay=stays.find(candidate=>candidate.id===record.id);const folio=folios.find(candidate=>candidate.id===record.id);const periods=folioEntries.filter(entry=>data(entry)?.sourceType==='ACCOMMODATION'&&data(entry)?.reservationId===record.id).map(entry=>Number(data(entry)?.period));return stayCheckoutBlocker({stayStatus:String(data(stay)?.status||''),reservationStatus:String(data(record)?.status||''),folioStatus:String(data(folio)?.status||''),balanceMinor:Number(data(folio)?.balanceMinor||0),depositMinor:Number(data(folio)?.depositMinor||0),units:Number(data(record)?.units||0),accommodationPeriods:periods})};
 const checkOut=(record:BusinessRecord)=>{const blocker=checkoutBlocker(record);if(blocker){setNotice(blocker);return}void run('stay.checkOut','stays',record.id,{id:record.id})};
 const moving=reservations.find(record=>record.id===moveId);const destinationRoom=rooms.find(record=>record.id===destination);const moveBlocker=moving?roomMoveBlocker({stayId:moveId,currentRoomId:String(data(moving)?.roomId||''),destinationRoomId:destination,startsAt:String(data(moving)?.startsAt||''),endsAt:String(data(moving)?.endsAt||''),guestCount:Number(data(moving)?.guests||1),capacity:Number(data(destinationRoom)?.capacity||0),maintenanceState:String(data(destinationRoom)?.maintenanceState||''),housekeepingState:String(data(destinationRoom)?.housekeepingState||''),reservations:reservations.map(record=>({id:record.id,roomId:String(data(record)?.roomId||''),startsAt:String(data(record)?.startsAt||''),endsAt:String(data(record)?.endsAt||''),blockedUntil:String(data(record)?.blockedUntil||''),status:String(data(record)?.status||'')})),blocks:blocks.map(record=>({roomId:String(data(record)?.roomId||''),startsAt:String(data(record)?.startsAt||''),endsAt:String(data(record)?.endsAt||''),status:String(data(record)?.status||'')}))}):null;
 const move=async(event:React.FormEvent)=>{event.preventDefault();if(!moveId||!destination||!reason.trim()||moveBlocker||disabled||moveBusy)return;setMoveBusy(true);try{const outcome=await run('stay.move','stays',moveId,{id:moveId,roomId:destination,reason:reason.trim()});if(isCommandConfirmed(outcome)){setMoveId('');setDestination('');setReason('')}}finally{setMoveBusy(false)}};
 return <section className="space-y-5" data-guide-anchor="web.front-desk">
  <div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="flex items-center gap-2 text-2xl font-bold"><LogIn className="h-6 w-6 text-amber-300"/>Front Desk</h2><p className="mt-1 text-sm text-slate-400">Arrivals, current stays, departures, occupancy, and controlled room moves · {propertyTimeZone}.</p></div><div className="flex flex-wrap items-center gap-2"><label className="min-w-[240px] flex-1 sm:max-w-sm"><span className="sr-only">Search arrivals and stays</span><Search className="relative left-3 top-8 h-4 w-4 text-slate-500"/><input className={`${field} pl-9`} placeholder="Search guest, room, or reservation" value={query} onChange={event=>setQuery(event.target.value)}/></label><button disabled={disabled||!allowed(session,'rooms.operate')||!rooms.length} className={primary} title={!rooms.length?'Add a room before making a reservation.':undefined} onClick={()=>{setQuickMode('RESERVE');setQuickReservation(true);}}><CalendarPlus className="mr-1 inline h-4 w-4"/>Quick reservation</button><button className={button} disabled={disabled||!allowed(session,'rooms.operate')||!rooms.length} onClick={()=>{setQuickMode('WALK_IN');setQuickReservation(true);}}>Walk-in</button></div></div>
  {notice&&<p role="status" className="rounded-xl border border-slate-700 bg-slate-900 p-3 text-sm text-slate-300">{notice}</p>}
  <div className="grid gap-3 sm:grid-cols-3"><Metric label="Occupied / sellable rooms" value={`${new Set(stays.filter(record=>data(record)?.status==='CHECKED_IN').map(record=>data(record)?.roomId)).size} / ${rooms.filter(record=>data(record)?.maintenanceState==='AVAILABLE').length}`}/><Metric label="Arrivals" value={arrivals.length}/><Metric label="Departures" value={departures.length}/></div>
  <div className="grid gap-4 xl:grid-cols-2"><Queue title="Arrivals and overdue" icon={<LogIn className="h-4 w-4 text-sky-300"/>}>{arrivals.map(record=>{const roomRecord=rooms.find(candidate=>candidate.id===String(data(record)?.roomId));const ready=data(roomRecord)?.housekeepingState==='READY'&&data(roomRecord)?.maintenanceState==='AVAILABLE';const due=Date.parse(String(data(record)?.startsAt||''))<=Date.now();const blocker=!due?'Check-in opens at the reservation arrival time.':!ready?'Room must be clean and in service before check-in.':'';return <StayCard key={record.id} record={record} guest={guest} room={room} timeZone={propertyTimeZone}><div className="text-xs text-slate-500">{blocker||'Room ready for check-in'}</div><button disabled={disabled||!allowed(session,'rooms.operate')||!ready||!due} title={blocker||undefined} className={primary} onClick={()=>checkIn(record)}>Check in</button></StayCard>})}</Queue><Queue title="Departures and current stays" icon={<LogOut className="h-4 w-4 text-amber-300"/>}>{departures.map(record=><StayCard key={record.id} record={record} guest={guest} room={room} timeZone={propertyTimeZone}><button disabled={disabled||!allowed(session,'rooms.operate')} className={button} onClick={()=>checkOut(record)}>Check out</button><button disabled={disabled||!allowed(session,'rooms.operate')} className={button} onClick={()=>{setMoveId(record.id);setDestination(rooms.find(candidate=>candidate.id!==data(record)?.roomId&&data(candidate)?.maintenanceState==='AVAILABLE'&&data(candidate)?.housekeepingState==='READY')?.id||'')}}><ArrowRightLeft className="h-4 w-4"/>Move room</button></StayCard>)}</Queue></div>
  <Queue title="Checkout readiness" icon={<LogOut className="h-4 w-4 text-amber-300"/>}>{departures.map(record=>{const blocker=checkoutBlocker(record);return <article key={record.id} className="rounded-xl border border-slate-800 bg-slate-950 p-3"><div className="flex flex-wrap items-start justify-between gap-3"><div><b>{guest(String(data(record)?.customerId))} · Room {room(String(data(record)?.roomId))}</b><p className={`mt-1 text-sm ${blocker?'text-amber-200':'text-emerald-300'}`}>{blocker||'Ready for checkout. Accommodation is posted, the balance is settled, and no deposit remains unapplied.'}</p></div>{blocker&&<button type="button" className={button} disabled={!onOpenGuestAccount||!allowed(session,'folio.view')&&!allowed(session,'folio.manage')} onClick={()=>onOpenGuestAccount?.(record.id)}>Open Guest Accounts</button>}</div></article>})}</Queue>
  <Queue title="Reservations" icon={<BedDouble className="h-4 w-4 text-emerald-300"/>}>{filtered.filter(record=>!['CHECKED_IN','CHECKED_OUT','CANCELLED','NO_SHOW'].includes(String(data(record)?.status))).map(record=><StayCard key={record.id} record={record} guest={guest} room={room} timeZone={propertyTimeZone}><span className="text-xs text-slate-500">{String(data(record)?.status)}</span></StayCard>)}</Queue>
  {moveId&&<form className="rounded-2xl border border-amber-500/30 bg-amber-500/5 p-4" onSubmit={move}><h3 className="font-bold">Move stay</h3><p className="mt-1 text-sm text-slate-400">{guest(String(data(moving)?.customerId))} · {room(String(data(moving)?.roomId))} · {date(data(moving)?.startsAt,propertyTimeZone)} to {date(data(moving)?.endsAt,propertyTimeZone)}</p><div className="mt-3 grid gap-3 sm:grid-cols-2"><label className="text-sm">Destination room<select required className={field} value={destination} disabled={moveBusy} onChange={event=>setDestination(event.target.value)}><option value="">Select…</option>{rooms.filter(record=>record.id!==data(moving)?.roomId).map(record=><option key={record.id} value={record.id}>{name(record)} · {String(data(record)?.housekeepingState||'')} · {String(data(record)?.maintenanceState||'')}</option>)}</select></label><label className="text-sm">Reason<input required className={field} disabled={moveBusy} value={reason} onChange={event=>setReason(event.target.value)} placeholder="Guest request or room issue"/></label></div>{moveBlocker&&<p role="status" className="mt-3 rounded-lg border border-amber-700/40 p-2 text-sm text-amber-200">{moveBlocker}</p>}<div className="mt-3 flex gap-2"><button disabled={disabled||moveBusy||Boolean(moveBlocker)||!reason.trim()} aria-busy={moveBusy} className={primary}>{moveBusy?'Queueing…':'Confirm room move'}</button><button type="button" disabled={moveBusy} className={button} onClick={()=>setMoveId('')}>Cancel</button></div></form>}
  {checkInId&&reservations.find(r=>r.id===checkInId)&&<HospitalityCheckInDialog reservation={reservations.find(r=>r.id===checkInId)!} records={records} session={session} deviceId={deviceId} queue={queue} disabled={disabled} command={command} onClose={()=>setCheckInId('')} onActivity={onActivity}/>}
  {quickReservation&&<QuickReservationDialog mode={quickMode} records={records} deviceId={deviceId} rooms={rooms} customers={customers} reservations={reservations} blocks={blocks} rates={rates} policy={reservationPolicy(records,session)} session={session} disabled={disabled} timeZone={propertyTimeZone} command={command} onClose={()=>setQuickReservation(false)}/>}
 </section>;
}

function QuickReservationDialog({mode,records,deviceId,rooms,customers,reservations,blocks,rates,policy,session,disabled,timeZone,command,onClose}:{mode:'RESERVE'|'WALK_IN';records:BusinessRecord[];deviceId:string;policy:ReturnType<typeof reservationPolicy>;rooms:BusinessRecord[];customers:BusinessRecord[];reservations:BusinessRecord[];blocks:BusinessRecord[];rates:BusinessRecord[];session:WebSession;disabled:boolean;timeZone:string;command:CommandFn;onClose:()=>void}){
 const accounts=active(records,'paymentAccounts').filter(r=>r.data.method==='CASH'&&r.data.currency==='KES');const till=active(records,'tillSessions').find(r=>r.data.status==='OPEN'&&r.data.operatorId===session.actorId&&r.data.deviceId===deviceId);const [cashAccountId,setCashAccountId]=useState(accounts[0]?.id||''),[cashReceived,setCashReceived]=useState('');const cashAccount=accounts.find(r=>r.id===cashAccountId);
 const checkout=policy.nightlyCheckoutTime||'10:00';const roomTypeId=policy.standardRoomRateEnabled?policy.roomStayRoomTypeId:null;const configuredRate=rates.find(rate=>rate.id===policy.roomStayRatePlanId);
 const initialArrival=businessDateTimeInput(new Date(),timeZone);const initialDeparture=`${addBusinessDays(businessDate(new Date(),timeZone),1)}T${checkout}`;
 const reservationId=useRef(crypto.randomUUID()),newGuestId=useRef(crypto.randomUUID()),submitting=useRef(false);const [pendingOutcome,setPendingOutcome]=useState(false);
 const [roomId,setRoomId]=useState(rooms[0]?.id||'');const [customerId,setCustomerId]=useState(customers[0]?.id||'');const [newGuest,setNewGuest]=useState(false);const [guestName,setGuestName]=useState('');const [guestPhone,setGuestPhone]=useState('');const [stayType,setStayType]=useState<'NIGHTLY'|'DAY'>('NIGHTLY');const [guests,setGuests]=useState('1');const [arrival,setArrival]=useState(initialArrival);const [departure,setDeparture]=useState(initialDeparture);const [busy,setBusy]=useState(false);const [error,setError]=useState('');
 const selectedRoom=rooms.find(room=>room.id===roomId);const selectedRate=policy.standardRoomRateEnabled?configuredRate:stayType==='NIGHTLY'&&configuredRate?.data.roomTypeId===selectedRoom?.data.roomTypeId?configuredRate:rates.find(rate=>rate.data.roomTypeId===selectedRoom?.data.roomTypeId&&rate.data.mode===(stayType==='DAY'?'DAY_USE':'NIGHTLY'));
 let startUtc='',endUtc='',blocker:string|null=null,estimate='',quotedMinor=0,tenderMinor:number|null=null;
 try{startUtc=businessDateTimeToUtc(arrival,timeZone);endUtc=businessDateTimeToUtc(departure,timeZone);blocker=roomReservationBlocker({roomId,roomTypeId:String(data(selectedRoom)?.roomTypeId||''),configuredRoomTypeId:roomTypeId,maintenanceState:String(data(selectedRoom)?.maintenanceState||''),startsAt:startUtc,endsAt:endUtc,reservations:reservations.map(record=>({roomId:String(data(record)?.roomId||''),startsAt:String(data(record)?.startsAt||''),endsAt:String(data(record)?.endsAt||''),blockedUntil:String(data(record)?.blockedUntil||''),status:String(data(record)?.status||'')})),blocks:blocks.map(record=>({roomId:String(data(record)?.roomId||''),startsAt:String(data(record)?.startsAt||''),endsAt:String(data(record)?.endsAt||''),status:String(data(record)?.status||'')}))});const arrivalWall=businessDateTimeInput(startUtc,timeZone),departureWall=businessDateTimeInput(endUtc,timeZone);if(!blocker&&!selectedRate)blocker='The configured room-stay rate is unavailable. Review the room-stay settings before booking.';if(!blocker&&stayType==='NIGHTLY'&&departureWall.slice(11,16)!==checkout)blocker=`Nightly departure must be at ${checkout} property time.`;if(!blocker&&stayType==='DAY'&&(arrivalWall.slice(0,10)!==departureWall.slice(0,10)||departureWall.slice(11,16)>(policy?.dayStayCutoffTime||'18:00')))blocker=`Day stays must end on the arrival date by ${policy?.dayStayCutoffTime||'18:00'}.`;if(!blocker&&Number(guests)>Number(data(selectedRoom)?.capacity||0))blocker='Guest count exceeds this room capacity.';if(selectedRate){const quote=quoteRoomBooking(selectedRate,selectedRoom,policy,stayType,startUtc,endUtc);quotedMinor=quote.totalMinor;estimate=`${money(quote.totalMinor)} / ${quote.units} billing period${quote.units===1?'':'s'}`;}}catch(cause){blocker=cause instanceof Error?cause.message:'Enter valid business dates and times.';}
 if(!blocker&&mode==='WALK_IN'&&policy.cashUpfrontRequired&&quotedMinor>0){if(!allowed(session,'payment.record')||session.capabilities?.['operations.checkout']!==true)blocker='Use the enrolled cashier to receive upfront walk-in cash.';else if(!till||!cashAccount)blocker='Open your cashier shift and choose an active cash account before receiving guest cash.';try{tenderMinor=cashReceived?parseMoneyToMinor(cashReceived):null;}catch(error){blocker=error instanceof Error?error.message:'Enter the cash received.';}}
 const submit=async(event:React.FormEvent)=>{event.preventDefault();if(disabled||busy||submitting.current||pendingOutcome||blocker)return;if(mode==='WALK_IN'&&policy.cashUpfrontRequired&&quotedMinor>0&&(tenderMinor===null||tenderMinor<quotedMinor)){setError('Count enough physical cash to cover the booked accommodation.');return;}submitting.current=true;setBusy(true);setError('');try{let resolvedCustomerId=customerId;if(newGuest){if(!allowed(session,'customers.manage')){setError('Ask a manager to add this guest, or choose an existing guest.');return}if(!guestName.trim()){setError('Enter the guest name.');return}resolvedCustomerId=newGuestId.current;const guestOutcome=await command('record.save','customers',resolvedCustomerId,{collection:'customers',id:resolvedCustomerId,data:{name:guestName.trim(),phone:guestPhone.trim()}});if(!isCommandConfirmed(guestOutcome)){if(guestOutcome.kind==='PENDING'||guestOutcome.kind==='OUTCOME_UNKNOWN')setPendingOutcome(true);else if(guestOutcome.kind==='REJECTED'||guestOutcome.kind==='CONFLICT')newGuestId.current=crypto.randomUUID();setError(`Guest creation was not confirmed. ${outcomeMessage(guestOutcome,'Guest creation')} Do not place the reservation until it is confirmed.`);return}setCustomerId(resolvedCustomerId);setNewGuest(false)}if(!resolvedCustomerId){setError('Choose an existing guest or create a new guest.');return}const id=reservationId.current;const outcome=await command(mode==='WALK_IN'?'roomReservation.walkIn':'roomReservation.create','roomReservations',id,{id,...(mode==='WALK_IN'&&policy.cashUpfrontRequired&&quotedMinor>0?{payment:{accountId:cashAccountId,amountMinor:quotedMinor,cashTenderedMinor:tenderMinor,tillSessionId:till?.id}}:{}),roomId,ratePlanId:selectedRate?.id,customerId:resolvedCustomerId,stayType,guests:Number(guests),startsAt:startUtc,endsAt:endUtc,expectedVersions:[{collection:'roomReservations',id,version:0},...(mode==='WALK_IN'?[{collection:'folios',id,version:0},{collection:'stays',id,version:0},...(policy.cashUpfrontRequired&&quotedMinor>0&&till&&cashAccount?[{collection:'tillSessions',id:till.id,version:till.version},{collection:'paymentAccounts',id:cashAccount.id,version:cashAccount.version}]:[])]:[]),...(selectedRoom?[{collection:'rooms',id:selectedRoom.id,version:selectedRoom.version}]:[]),...(selectedRate?[{collection:'ratePlans',id:selectedRate.id,version:selectedRate.version}]:[]),{collection:'customers',id:resolvedCustomerId,version:customers.find(row=>row.id===resolvedCustomerId)?.version||1}]});if(isCommandConfirmed(outcome))onClose();else{if(outcome.kind==='PENDING'||outcome.kind==='OUTCOME_UNKNOWN')setPendingOutcome(true);else if(outcome.kind==='REJECTED'||outcome.kind==='CONFLICT')reservationId.current=crypto.randomUUID();setError(`${outcomeMessage(outcome,'Reservation')} Review Activity before retrying.`);}}catch{setPendingOutcome(true);setError('The reservation outcome could not be checked. Recover the original update in Activity before making another booking.')}finally{submitting.current=false;setBusy(false)}};
 return <Dialog title={mode==='WALK_IN'?'Walk-in check-in':'Quick reservation'} onClose={busy?()=>undefined:onClose} footer={<><button type="button" disabled={busy} className={button} onClick={onClose}>Cancel</button><button type="submit" form="quick-reservation-form" disabled={disabled||busy||pendingOutcome||Boolean(blocker)||(!newGuest&&!customerId)||(!roomId)} aria-busy={busy} className={primary}>{busy?'Saving…':'Create reservation'}</button></>}><form id="quick-reservation-form" className="space-y-3" onSubmit={event=>void submit(event)}><label className="block text-sm">Room<select required className={`${field} mt-1`} value={roomId} onChange={event=>setRoomId(event.target.value)}>{rooms.map(room=><option key={room.id} value={room.id}>{String(data(room)?.number||name(room))} · {String(data(room)?.housekeepingState||'UNKNOWN')} · {String(data(room)?.maintenanceState||'AVAILABLE')}</option>)}</select></label>{newGuest?<div className="grid gap-3 sm:grid-cols-2"><label className="text-sm">Guest name<input autoFocus required className={`${field} mt-1`} value={guestName} onChange={event=>setGuestName(event.target.value)}/></label><label className="text-sm">Phone (optional)<input className={`${field} mt-1`} value={guestPhone} onChange={event=>setGuestPhone(event.target.value)}/></label><button type="button" className="text-left text-sm text-amber-300 underline" onClick={()=>setNewGuest(false)}>Choose existing guest instead</button></div>:<div className="flex items-end gap-2"><label className="block flex-1 text-sm">Guest<select required className={`${field} mt-1`} value={customerId} onChange={event=>setCustomerId(event.target.value)}><option value="">Select a guest</option>{customers.map(customer=><option key={customer.id} value={customer.id}>{name(customer)}</option>)}</select></label>{allowed(session,'customers.manage')&&<button type="button" className={button} onClick={()=>setNewGuest(true)}><UserPlus className="mr-1 inline h-4 w-4"/>New guest</button>}</div>}<div className="grid gap-3 sm:grid-cols-2"><label className="text-sm">Stay type<select className={`${field} mt-1`} value={stayType} onChange={event=>{const type=event.target.value as 'NIGHTLY'|'DAY';setStayType(type);setDeparture(type==='DAY'?`${arrival.slice(0,10)}T${policy.dayStayCutoffTime||'18:00'}`:`${addBusinessDays(arrival.slice(0,10),1)}T${checkout}`);}}><option value="NIGHTLY">Nightly · departure {checkout}</option><option value="DAY">Day stay · cutoff {policy?.dayStayCutoffTime||'18:00'}</option></select></label><label className="text-sm">Guests<input required min="1" type="number" className={`${field} mt-1`} value={guests} onChange={event=>setGuests(event.target.value)}/></label><label className="text-sm">Arrival ({timeZone})<input required type="datetime-local" data-business-timezone={timeZone} className={`${field} mt-1`} value={arrival} onChange={event=>setArrival(event.target.value)}/></label><label className="text-sm">Departure ({timeZone})<input required type="datetime-local" data-business-timezone={timeZone} className={`${field} mt-1`} value={departure} onChange={event=>setDeparture(event.target.value)}/></label></div><div className="rounded-xl border border-slate-700 bg-slate-950 p-3 text-sm"><b>Availability and rate preview</b><p className="mt-1">{blocker?<span className="text-amber-300">{blocker}</span>:<span className="text-emerald-300">No committed room or block overlap found; the server rechecks before saving.</span>}</p><p className="mt-1 text-slate-400">{selectedRate?`${money(Number(data(selectedRate)?.priceMinor||0))} per ${stayType==='DAY'?'day':'night'} · estimated accommodation ${estimate}`:'Configure the room-stay rate before creating this reservation.'}</p></div>{mode==='WALK_IN'&&policy.cashUpfrontRequired&&quotedMinor>0&&<section className="space-y-3 rounded-xl border border-amber-600/40 p-3"><p className="text-sm">Upfront accommodation cash <strong>{money(quotedMinor)}</strong>. Check-in, payment and drawer entry commit together; wait for server confirmation.</p><FormField label="Cash account"><select className={field} value={cashAccountId} disabled={busy||pendingOutcome} onChange={event=>setCashAccountId(event.target.value)}><option value="">Choose cash account</option>{accounts.map(r=><option key={r.id} value={r.id}>{name(r)}</option>)}</select></FormField><FormField label="Cash received (KES)"><input className={field} inputMode="decimal" value={cashReceived} disabled={busy||pendingOutcome} onChange={event=>setCashReceived(event.target.value)}/></FormField><p className="text-sm">Change {money(tenderMinor===null?0:Math.max(0,tenderMinor-quotedMinor))}</p></section>}{error&&<p role="alert" className="text-sm text-rose-300">{error}</p>}</form></Dialog>;
}

function BaseGuestAccountsView({records,session,disabled,command,deviceId,initialReservationId,queue=[]}:{records:BusinessRecord[];session:WebSession;disabled:boolean;command:CommandFn;deviceId:string;initialReservationId?:string;queue?:QueuedCommand[]}){
 const reservations=active(records,'roomReservations');const folios=active(records,'folios');const entries=active(records,'folioEntries');const customers=active(records,'customers');const rooms=active(records,'rooms');const accounts=active(records,'paymentAccounts');const services=active(records,'hotelServices');
 const propertyTimeZone=String(data(active(records,'hospitalitySettings')[0])?.timeZone||session.propertyContext?.timeZone||'Africa/Nairobi');
 const [selectedId,setSelectedId]=useState(initialReservationId||folios[0]?.id||reservations[0]?.id||'');const [amount,setAmount]=useState('');const [cashTendered,setCashTendered]=useState('');const [reference,setReference]=useState('');const [externalConfirmed,setExternalConfirmed]=useState(false);const [receivedAtLocal,setReceivedAtLocal]=useState(()=>businessDateTimeInput(new Date(),propertyTimeZone));const [accountId,setAccountId]=useState(accounts[0]?.id||'');const [serviceId,setServiceId]=useState(services[0]?.id||'');const [quantity,setQuantity]=useState('1');const [outcome,setOutcome]=useState<CommandOutcome|null>(null);const [busy,setBusy]=useState(false);const busyRef=useRef(false);
 useEffect(()=>{if(initialReservationId)setSelectedId(initialReservationId);},[initialReservationId]);
 const ownedTill=active(records,'tillSessions').find(r=>r.data.status==='OPEN'&&r.data.operatorId===session.actorId&&r.data.deviceId===deviceId);
 const pendingAction=queue.some(r=>['PENDING_SYNC','OUTCOME_UNKNOWN'].includes(r.state)&&['folio.pay','folio.deposit','stay.extend'].includes(r.command.operation)&&r.command.payload.id===selectedId);
 const reservation=reservations.find(record=>record.id===selectedId);const folio=folios.find(record=>record.id===selectedId);const selectedAccount=accounts.find(record=>record.id===accountId);const guest=name(customers.find(record=>record.id===data(reservation)?.customerId));const room=name(rooms.find(record=>record.id===data(reservation)?.roomId));const folioEntries=entries.filter(record=>data(record)?.folioId===selectedId);
 useEffect(()=>{if(outcome?.kind!=='PENDING'&&outcome?.kind!=='OUTCOME_UNKNOWN')return;const original=queue.find(row=>row.id===outcome.commandId);if(original?.state==='SYNCHRONIZED'&&entries.some(row=>row.data.sourceCommandId===original.id)){setOutcome({kind:'CONFIRMED',commandId:original.id});setAmount('');setCashTendered('');setReference('');setExternalConfirmed(false);}else if(original?.state==='REJECTED'||original?.state==='CONFLICT'){setOutcome({kind:original.state,commandId:original.id,message:original.result?.error?.message||'Review the current guest balance before resubmitting.'});}},[queue,outcome,entries]);
 const run=async(operation:string,payload:Record<string,unknown>):Promise<CommandOutcome>=>{if(disabled||busyRef.current||pendingAction||outcome?.kind==='PENDING'||outcome?.kind==='OUTCOME_UNKNOWN'){const blocked:CommandOutcome={kind:'BLOCKED',message:'Wait for the current guest-account action to finish before submitting another.'};setOutcome(blocked);return blocked}busyRef.current=true;setBusy(true);setOutcome(null);try{const result=await command(operation,'folios',selectedId,payload);setOutcome(result);return result}catch{const blocked:CommandOutcome={kind:'BLOCKED',message:'The guest-account action could not be confirmed. Check connectivity and permissions, then review Activity before retrying.'};setOutcome(blocked);return blocked}finally{busyRef.current=false;setBusy(false)}};
 const pay=async(operation:'folio.deposit'|'folio.pay')=>{if(operation==='folio.deposit'&&(data(reservation)?.rateSnapshot as Record<string,unknown>|undefined)?.cashUpfrontRequired===true){setOutcome({kind:'BLOCKED',message:'This booking uses upfront cash; new deposits are not enabled.'});return;}let minorAmount:number,cashMinor:number|undefined;const isCash=data(selectedAccount)?.method==='CASH',isMpesa=data(selectedAccount)?.method==='MPESA';try{minorAmount=parseMoneyToMinor(amount);cashMinor=isCash?parseMoneyToMinor(cashTendered||amount):undefined;}catch(error){setOutcome({kind:'BLOCKED',message:error instanceof Error?error.message:'Enter a valid amount.'});return;}if(isCash&&(data(reservation)?.rateSnapshot as Record<string,unknown>|undefined)?.cashUpfrontRequired===true&&(!ownedTill||session.capabilities?.['operations.checkout']!==true)){setOutcome({kind:'BLOCKED',message:'Use the enrolled cashier and their open shift to receive this guest cash.'});return;}if(!Number.isSafeInteger(minorAmount)||minorAmount<=0||isCash&&(!Number.isSafeInteger(cashMinor)||Number(cashMinor)<minorAmount)){setOutcome({kind:'BLOCKED',message:'Enter a valid payment and, for cash, enough tender to cover it. The folio has not changed.'});return}if(!isCash&&!externalConfirmed){setOutcome({kind:'BLOCKED',message:'Confirm that staff manually verified the funds were received before recording this external payment.'});return}let actualReceivedAt:string|undefined;if(isMpesa){if(!reference.trim()){setOutcome({kind:'BLOCKED',message:'Enter the actual M-Pesa transaction reference.'});return}try{actualReceivedAt=businessDateTimeToUtc(receivedAtLocal,propertyTimeZone)}catch(error){setOutcome({kind:'BLOCKED',message:error instanceof Error?error.message:'Enter the actual M-Pesa receipt time.'});return}}const result=await run(operation,{id:selectedId,amountMinor:minorAmount,accountId,...(isCash?{cashTenderedMinor:cashMinor,...(ownedTill&&session.capabilities?.['operations.checkout']===true?{tillSessionId:ownedTill.id}:{})}:{manuallyConfirmed:true,reference,...(isMpesa?{receivedAmountMinor:minorAmount,receivedAt:actualReceivedAt}:{})})});if(isCommandConfirmed(result)){setAmount('');setCashTendered('');setReference('');setExternalConfirmed(false)}};
 const blockingOutcome=outcome&&['OUTCOME_UNKNOWN','REJECTED','CONFLICT','BLOCKED'].includes(outcome.kind);
 return <section className="space-y-5" data-guide-anchor="web.guest-accounts"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="flex items-center gap-2 text-2xl font-bold"><WalletCards className="h-6 w-6 text-amber-300"/>Guest Accounts</h2><p className="mt-1 text-sm text-slate-400">Folios, deposits, accommodation, services, settlement, and conserved checkout.</p></div><select disabled={disabled||busy} aria-label="Select a guest account" className={`${field} max-w-md`} value={selectedId} onChange={event=>setSelectedId(event.target.value)}><option value="">Select a guest account</option>{reservations.map(record=><option key={record.id} value={record.id}>{name(customers.find(customer=>customer.id===data(record)?.customerId))} · {name(rooms.find(candidate=>candidate.id===data(record)?.roomId))} · {String(data(record)?.status)}</option>)}</select></div>{outcome&&<p role={blockingOutcome?'alert':'status'} aria-live={blockingOutcome?'assertive':'polite'} className="rounded-xl border border-slate-700 bg-slate-900 p-3 text-sm text-slate-300">{outcomeMessage(outcome,'Guest account action')}</p>}{!selectedId&&<Empty text="Select a reservation or folio to begin."/>}{selectedId&&<><div className="grid gap-3 sm:grid-cols-3"><Metric label="Guest" value={guest}/><Metric label="Balance" value={money(data(folio)?.balanceMinor)}/><Metric label="Deposit" value={money(data(folio)?.depositMinor)}/></div><div className="grid gap-4 xl:grid-cols-2"><section className="rounded-2xl border border-slate-800 bg-slate-900 p-4"><h3 className="font-bold">Account actions</h3><div className="mt-3 grid gap-3 sm:grid-cols-2"><label className="text-sm sm:col-span-2">Payment account<select disabled={disabled||busy} className={field} value={accountId} onChange={event=>setAccountId(event.target.value)}><option value="">Select…</option>{accounts.map(record=><option key={record.id} value={record.id}>{name(record)}</option>)}</select></label><label className="text-sm">Amount (KES)<input disabled={disabled||busy} className={field} type="number" min="0.01" step="0.01" inputMode="decimal" value={amount} onChange={event=>setAmount(event.target.value)}/></label>{data(selectedAccount)?.method==='CASH'?<label className="text-sm">Cash tendered (KES)<input disabled={disabled||busy} className={field} type="number" min={amount||"0.01"} step="0.01" value={cashTendered} onChange={event=>setCashTendered(event.target.value)} placeholder={amount}/></label>:<label className="text-sm">External reference<input disabled={disabled||busy} className={field} value={reference} onChange={event=>setReference(event.target.value)} placeholder="Receipt or transaction reference"/></label>}{data(selectedAccount)?.method!=='CASH'&&<><label className="text-sm sm:col-span-2"><input type="checkbox" checked={externalConfirmed} disabled={disabled||busy} onChange={event=>setExternalConfirmed(event.target.checked)}/> I manually verified that these external funds were received.</label>{data(selectedAccount)?.method==='MPESA'&&<label className="text-sm">Actual M-Pesa receipt time ({propertyTimeZone})<input type="datetime-local" className={field} value={receivedAtLocal} disabled={disabled||busy} onChange={event=>setReceivedAtLocal(event.target.value)}/></label>}</>}<div className="flex items-end gap-2"><button type="button" disabled={disabled||busy||pendingAction||outcome?.kind==='PENDING'||outcome?.kind==='OUTCOME_UNKNOWN'||!folio||!amount||!accountId||!allowed(session,'payment.record')||data(selectedAccount)?.method!=='CASH'&&!externalConfirmed} aria-busy={busy} className={button} title={(data(reservation)?.rateSnapshot as Record<string,unknown>|undefined)?.cashUpfrontRequired===true?'This booking uses upfront cash; new deposits are not enabled.':undefined} onClick={()=>void pay('folio.deposit')}>{(data(reservation)?.rateSnapshot as Record<string,unknown>|undefined)?.cashUpfrontRequired===true?'Deposits disabled':'Record deposit'}</button><button type="button" disabled={disabled||busy||pendingAction||outcome?.kind==='PENDING'||outcome?.kind==='OUTCOME_UNKNOWN'||!folio||!amount||!accountId||!allowed(session,'payment.record')||data(selectedAccount)?.method!=='CASH'&&!externalConfirmed} aria-busy={busy} className={primary} onClick={()=>void pay('folio.pay')}>Settle balance</button></div><button type="button" disabled={disabled||busy||!allowed(session,'folio.manage')} aria-busy={busy} className={button} onClick={()=>void run('folio.postAccommodation',{id:selectedId,settleBookedStay:false})}>Post due accommodation</button><button type="button" disabled={disabled||busy||!allowed(session,'folio.manage')} aria-busy={busy} className={button} onClick={()=>void run('folio.postAccommodation',{id:selectedId,settleBookedStay:true})}>Post booked accommodation</button><button type="button" disabled={disabled||busy||!allowed(session,'folio.view')} className={button} onClick={()=>void run('folio.print',{id:selectedId})}>Print folio</button><button type="button" disabled={disabled||busy||!allowed(session,'folio.manage')} aria-busy={busy} className={button} onClick={()=>void run('folio.applyDeposit',{id:selectedId,amountMinor:Math.min(Number(data(folio)?.depositMinor||0),Number(data(folio)?.balanceMinor||0))})}>Apply available deposit</button><label className="text-sm">Hotel service<select disabled={disabled||busy} className={field} value={serviceId} onChange={event=>setServiceId(event.target.value)}><option value="">Select…</option>{services.map(record=><option key={record.id} value={record.id}>{name(record)} · {money(data(record)?.priceMinor)}</option>)}</select></label><label className="text-sm">Quantity<input disabled={disabled||busy} className={field} type="number" min="1" value={quantity} onChange={event=>setQuantity(event.target.value)}/></label><button type="button" disabled={disabled||busy||!serviceId||!allowed(session,'folio.manage')} aria-busy={busy} className={button} onClick={()=>void run('folio.postService',{id:selectedId,serviceId,quantity:Number(quantity)})}>Post service</button></div></section><section className="rounded-2xl border border-slate-800 bg-slate-900 p-4"><h3 className="font-bold">Folio history</h3><div className="mt-3 space-y-2">{folioEntries.map(record=><article key={record.id} className="rounded-xl bg-slate-950 p-3 text-sm"><div className="flex justify-between gap-3"><b>{String(data(record)?.description||data(record)?.kind||'Folio entry')}</b><span>{money(data(record)?.grossMinor||data(record)?.amountMinor||data(record)?.balanceDeltaMinor)}</span></div><p className="mt-1 text-xs text-slate-500">{date(data(record)?.postedAt)}</p></article>)}{folioEntries.length===0&&<Empty text="No folio entries yet."/>}</div></section></div><section className="rounded-2xl border border-amber-500/30 bg-amber-500/5 p-4"><div className="flex items-start gap-3"><ShieldAlert className="mt-1 h-5 w-5 text-amber-300"/><div><b>Checkout conservation</b><p className="mt-1 text-sm text-slate-400">Checkout is enabled only when booked accommodation is posted, the balance is zero, and no deposit remains unapplied.</p><button type="button" disabled={disabled||busy||!reservation||data(reservation)?.status!=='CHECKED_IN'||!allowed(session,'rooms.operate')} aria-busy={busy} className={`${primary} mt-3`} onClick={()=>void run('stay.checkOut',{id:selectedId})}>Check out guest</button></div></div></section></>}</section>;
}

export function WebGuestAccountsView({records,session,disabled,command,deviceId,initialReservationId,queue=[]}:{records:BusinessRecord[];session:WebSession;disabled:boolean;command:CommandFn;deviceId:string;initialReservationId?:string;queue?:QueuedCommand[]}){
 return <><BaseGuestAccountsView records={records} session={session} disabled={disabled} command={command} deviceId={deviceId} initialReservationId={initialReservationId} queue={queue}/><FolioChargeReversal records={records} session={session} disabled={disabled} command={command}/></>;
}

function FolioChargeReversal({records,session,disabled,command}:{records:BusinessRecord[];session:WebSession;disabled:boolean;command:CommandFn}){
 const folios=active(records,'folios');const entries=active(records,'folioEntries');const [folioId,setFolioId]=useState(folios[0]?.id||'');const [entryId,setEntryId]=useState('');const [reason,setReason]=useState('');const [busy,setBusy]=useState(false);const [notice,setNotice]=useState('');
 const charges=entries.filter(entry=>data(entry)?.folioId===folioId&&data(entry)?.kind==='CHARGE'&&!entries.some(other=>data(other)?.kind==='REVERSAL'&&data(other)?.reversesEntryId===entry.id));
 const selected=charges.find(entry=>entry.id===entryId),selectedFolio=folios.find(row=>row.id===folioId),roomChargeOrderId=String((data(selected)?.details as Record<string,unknown>|undefined)?.orderId||''),roomChargeOrder=records.find(row=>row.collection==='orders'&&row.id===roomChargeOrderId);
 const reverse=async()=>{if(!selected||!selectedFolio||!reason.trim()||disabled||!allowed(session,'folio.reverse'))return;if(data(selected)?.sourceType==='POS'&&!roomChargeOrder){setNotice('Synchronize the linked POS order and review it before reversing this room charge.');return}setBusy(true);setNotice('');try{const expectedVersions=[{collection:'folios',id:selectedFolio.id,version:selectedFolio.version},{collection:'folioEntries',id:selected.id,version:selected.version},...(data(selected)?.sourceType==='POS'&&roomChargeOrder?[{collection:'orders',id:roomChargeOrder.id,version:roomChargeOrder.version}]:[])];const outcome=await command('folio.reverse','folios',folioId,{id:folioId,entryId:selected.id,reason:reason.trim(),expectedVersions});setNotice(outcomeMessage(outcome,'Folio charge reversal'));if(isCommandConfirmed(outcome)){setEntryId('');setReason('')}}catch(error){setNotice(error instanceof Error?error.message:'The reversal outcome could not be checked. Review Activity before retrying.')}finally{setBusy(false)}};
 return <section className="rounded-2xl border border-rose-700/30 bg-rose-950/10 p-4" aria-label="Reverse an unpaid folio charge"><h3 className="font-bold">Reverse an unpaid folio charge</h3><BlockerCard title="Reversal limits">Only an unreversed charge still represented in the guest's outstanding balance can be reversed. Paid charges require the separate refund workflow.</BlockerCard>{notice&&<p role="status" className="mt-3 rounded-lg border border-slate-700 p-3 text-sm">{notice}</p>}<div className="mt-3 grid gap-3 md:grid-cols-3"><FormField label="Guest folio"><select className={field} value={folioId} onChange={event=>{setFolioId(event.target.value);setEntryId('')}}><option value="">Select folio</option>{folios.filter(folio=>data(folio)?.status==='OPEN').map(folio=><option key={folio.id} value={folio.id}>{String(data(folio)?.reservationId||folio.id)} · balance {money(data(folio)?.balanceMinor)}</option>)}</select></FormField><FormField label="Charge"><select className={field} value={entryId} onChange={event=>setEntryId(event.target.value)}><option value="">Select an unreversed charge</option>{charges.map(entry=><option key={entry.id} value={entry.id}>{String(data(entry)?.description||data(entry)?.sourceType||'Folio charge')} · {money(data(entry)?.grossMinor)}</option>)}</select></FormField><FormField label="Reason" hint="Required for the audit record"><textarea className={field} value={reason} maxLength={1000} onChange={event=>setReason(event.target.value)} placeholder="Explain the correction"/></FormField></div><BusyButton busy={busy} disabled={disabled||!allowed(session,'folio.reverse')||!selected||!reason.trim()} className="mt-3" onClick={()=>void reverse()}>Review and reverse charge</BusyButton></section>;
}

export function WebHousekeepingView({records,session,disabled,command}:{records:BusinessRecord[];session:WebSession;disabled:boolean;command:CommandFn}){
 const rooms=active(records,'rooms');const reservations=active(records,'roomReservations');const blocks=active(records,'roomBlocks');const [query,setQuery]=useState('');const [notice,setNotice]=useState('');const [releaseBlock,setReleaseBlock]=useState<BusinessRecord|null>(null);const [inspection,setInspection]=useState('');
 const timeZone=String(session.propertyContext?.timeZone||'Africa/Nairobi');const [blockRoom,setBlockRoom]=useState<BusinessRecord|null>(null);const [reportRoom,setReportRoom]=useState<BusinessRecord|null>(null);const [blockStart,setBlockStart]=useState(()=>businessDateTimeInput(new Date(),timeZone));const [blockEnd,setBlockEnd]=useState(()=>businessDateTimeInput(new Date(Date.now()+86400000),timeZone));const [blockReason,setBlockReason]=useState('');const [reportDescription,setReportDescription]=useState('');const [reportPriority,setReportPriority]=useState('MEDIUM');const [actionBusy,setActionBusy]=useState(false);
 const visible=rooms.filter(record=>`${name(record)} ${data(record)?.floor||''} ${data(record)?.wing||''}`.toLowerCase().includes(query.toLowerCase()));
 const transition=(record:BusinessRecord,state:string)=>void run('room.housekeeping','rooms',record.id,{id:record.id,state});
 const run=async(operation:string,collection:string,id:string,payload:Record<string,unknown>):Promise<CommandOutcome>=>{setNotice('');try{const outcome=await command(operation,collection,id,payload);setNotice(outcomeMessage(outcome,'Housekeeping action'));return outcome}catch{const blocked:CommandOutcome={kind:'BLOCKED',message:'The Housekeeping action could not be confirmed. Check connectivity and permissions, then review Activity before retrying.'};setNotice(blocked.message);return blocked}};
 const condition=(record:BusinessRecord)=>{if(data(record)?.maintenanceState==='OUT_OF_SERVICE')void run('maintenance.returnToService','rooms',record.id,{id:record.id,expectedVersions:[{collection:'rooms',id:record.id,version:record.version}]});else{setReportDescription('');setReportPriority('MEDIUM');setReportRoom(record);}};
 const release=(block:BusinessRecord)=>{setInspection('');setReleaseBlock(block)};
 const confirmRelease=async(event:React.FormEvent)=>{event.preventDefault();if(!releaseBlock||!inspection.trim()||disabled||!allowed(session,'rooms.manage'))return;setActionBusy(true);try{if(isCommandConfirmed(await run('room.unblock','roomBlocks',releaseBlock.id,{id:releaseBlock.id,inspection:inspection.trim()})))setReleaseBlock(null)}finally{setActionBusy(false)}};
 const confirmBlock=async(event:React.FormEvent)=>{event.preventDefault();if(!blockRoom||disabled||!allowed(session,'rooms.manage'))return;let startsAt:string,endsAt:string;try{startsAt=businessDateTimeToUtc(blockStart,timeZone);endsAt=businessDateTimeToUtc(blockEnd,timeZone);if(Date.parse(endsAt)<=Date.parse(startsAt))throw new RangeError('The release time must be after the block starts.')}catch(error){setNotice(error instanceof Error?error.message:'Enter a valid room block interval.');return}const id=crypto.randomUUID();setActionBusy(true);try{if(isCommandConfirmed(await run('room.block','roomBlocks',id,{id,roomId:blockRoom.id,startsAt,endsAt,reason:blockReason.trim()}))){setBlockRoom(null);setBlockReason('')}}finally{setActionBusy(false)}};
 const confirmReport=async(event:React.FormEvent)=>{event.preventDefault();if(!reportRoom||!reportDescription.trim()||disabled||!allowed(session,'maintenance.manage'))return;const id=crypto.randomUUID();setActionBusy(true);try{if(isCommandConfirmed(await run('maintenance.open','maintenanceWorkOrders',id,{id,roomId:reportRoom.id,title:`Room maintenance - ${reportPriority.toLowerCase()} priority`,fault:reportDescription.trim(),reason:reportDescription.trim(),expectedVersions:[{collection:'rooms',id:reportRoom.id,version:reportRoom.version}]}))){setReportRoom(null);setReportDescription('');setReportPriority('MEDIUM')}}finally{setActionBusy(false)}};
 const columns=['DIRTY','CLEANING','INSPECTED','READY'];const next:{[key:string]:string}={DIRTY:'CLEANING',CLEANING:'INSPECTED',INSPECTED:'READY'};
  return <section className="space-y-5" data-guide-anchor="web.housekeeping">
   <div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="flex items-center gap-2 text-2xl font-bold"><ClipboardCheck className="h-6 w-6 text-amber-300"/>Housekeeping</h2><p className="mt-1 text-sm text-slate-400">Room readiness is separate from occupancy. Transitions are versioned and audited.</p></div><label className="min-w-[240px] sm:max-w-sm"><span className="sr-only">Filter rooms</span><input className={field} placeholder="Filter room, floor, or wing" value={query} onChange={event=>setQuery(event.target.value)}/></label></div>
   {notice&&<p role="status" className="rounded-xl border border-slate-700 bg-slate-900 p-3 text-sm text-slate-300">{notice}</p>}
   <div className="grid gap-4 xl:grid-cols-4">{columns.map(state=><section key={state} className="min-w-0 rounded-2xl border border-slate-800 bg-slate-900 p-3"><div className="mb-3 flex items-center justify-between"><b>{state}</b><span className="rounded-full bg-slate-950 px-2 py-1 text-xs text-slate-500">{visible.filter(record=>(data(record)?.housekeepingState||'UNKNOWN')===state).length}</span></div><div className="space-y-2">{visible.filter(record=>(data(record)?.housekeepingState||'UNKNOWN')===state).map(record=><article key={record.id} className="rounded-xl bg-slate-950 p-3"><div className="flex justify-between gap-2"><b>Room {name(record)}</b>{data(record)?.maintenanceState==='OUT_OF_SERVICE'&&<ShieldAlert className="h-4 w-4 text-rose-300"/>}</div>{reservations.filter(reservation=>data(reservation)?.roomId===record.id&&['RESERVED','CHECKED_IN'].includes(String(data(reservation)?.status))).map(reservation=><p key={reservation.id} className="mt-2 text-xs text-sky-300">{String(data(reservation)?.status)} · departure {date(data(reservation)?.endsAt,timeZone)}</p>)}{blocks.filter(block=>data(block)?.roomId===record.id&&data(block)?.status==='ACTIVE').map(block=><div key={block.id} className="mt-2 rounded-lg border border-amber-800/30 p-2 text-xs text-amber-200">{String(data(block)?.reason)}<button disabled={disabled||actionBusy||!allowed(session,'rooms.manage')} className="mt-1 block underline disabled:cursor-not-allowed disabled:opacity-40" onClick={()=>release(block)}>Release block</button></div>)}<div className="mt-3 flex flex-wrap gap-2">{next[state]&&<button disabled={disabled||!allowed(session,'rooms.operate')} className={button} onClick={()=>transition(record,next[state])}>Advance</button>}{state==='INSPECTED'&&<button disabled={disabled||!allowed(session,'rooms.operate')} className={button} onClick={()=>transition(record,'DIRTY')}>Fail inspection</button>}{state==='READY'&&<button disabled={disabled||!allowed(session,'rooms.operate')} className={button} onClick={()=>transition(record,'DIRTY')}>Mark dirty</button>}<button disabled={disabled||!allowed(session,'maintenance.manage')} className={button} onClick={()=>condition(record)}>{data(record)?.maintenanceState==='OUT_OF_SERVICE'?'Return to service':'Out of order'}</button>{allowed(session,'rooms.manage')&&<button disabled={disabled} className={button} onClick={()=>{setBlockStart(businessDateTimeInput(new Date(),timeZone));setBlockEnd(businessDateTimeInput(new Date(Date.now()+86400000),timeZone));setBlockReason('');setBlockRoom(record)}}>Block room</button>}{allowed(session,'maintenance.manage')&&<button disabled={disabled} className={button} onClick={()=>{setReportDescription('');setReportPriority('MEDIUM');setReportRoom(record)}}>Report maintenance</button>}</div></article>)}</div></section>)}</div>
   {releaseBlock&&<Dialog title="Release room block" onClose={actionBusy?()=>undefined:()=>setReleaseBlock(null)}><form className="space-y-3" onSubmit={confirmRelease}><label className="block text-sm">Inspection and release note<textarea required autoFocus className={`${field} mt-1`} value={inspection} onChange={event=>setInspection(event.target.value)}/></label><div className="flex justify-end gap-2"><button type="button" disabled={actionBusy} className={button} onClick={()=>setReleaseBlock(null)}>Cancel</button><button disabled={disabled||actionBusy||!allowed(session,'rooms.manage')||!inspection.trim()} aria-busy={actionBusy} className={primary}>{actionBusy?'Releasing…':'Release block'}</button></div></form></Dialog>}
   {blockRoom&&<Dialog title={`Block room ${name(blockRoom)}`} onClose={actionBusy?()=>undefined:()=>setBlockRoom(null)} footer={<><button disabled={actionBusy} type="button" className={button} onClick={()=>setBlockRoom(null)}>Cancel</button><button disabled={disabled||actionBusy||!allowed(session,'rooms.manage')||!blockReason.trim()} aria-busy={actionBusy} type="submit" form="room-block-form" className={primary}>{actionBusy?'Blocking…':'Block room'}</button></>}><form id="room-block-form" className="space-y-3" onSubmit={event=>void confirmBlock(event)}><p className="text-sm text-slate-400">Times use {timeZone}. Active reservations or existing blocks are rejected by the business server.</p><label className="block text-sm">Block starts<input required type="datetime-local" data-business-timezone={timeZone} className={`${field} mt-1`} value={blockStart} onChange={event=>setBlockStart(event.target.value)}/></label><label className="block text-sm">Block ends<input required type="datetime-local" data-business-timezone={timeZone} className={`${field} mt-1`} value={blockEnd} onChange={event=>setBlockEnd(event.target.value)}/></label><label className="block text-sm">Reason<textarea required className={`${field} mt-1`} value={blockReason} onChange={event=>setBlockReason(event.target.value)}/></label></form></Dialog>}
   {reportRoom&&<Dialog title={`Report maintenance · ${name(reportRoom)}`} onClose={actionBusy?()=>undefined:()=>setReportRoom(null)} footer={<><button disabled={actionBusy} type="button" className={button} onClick={()=>setReportRoom(null)}>Cancel</button><button disabled={disabled||actionBusy||!allowed(session,'maintenance.manage')||!reportDescription.trim()} aria-busy={actionBusy} type="submit" form="room-maintenance-report-form" className={primary}>{actionBusy?'Reporting…':'Report problem'}</button></>}><form id="room-maintenance-report-form" className="space-y-3" onSubmit={event=>void confirmReport(event)}><p className="text-sm text-slate-400">This opens a maintenance work order and blocks the selected room until repair and inspection are recorded.</p><label className="block text-sm">What needs attention?<textarea required maxLength={4000} autoFocus className={`${field} mt-1`} value={reportDescription} onChange={event=>setReportDescription(event.target.value)}/></label><label className="block text-sm">Priority<select className={`${field} mt-1`} value={reportPriority} onChange={event=>setReportPriority(event.target.value)}><option value="LOW">Low</option><option value="MEDIUM">Normal</option><option value="HIGH">High</option><option value="CRITICAL">Critical</option></select></label></form></Dialog>}
  </section>;
}

function StayCard({record,guest,room,timeZone='Africa/Nairobi',children}:{record:BusinessRecord;guest:(id:string)=>string;room:(id:string)=>string;timeZone?:string;children:React.ReactNode}){return <article className="rounded-xl border border-slate-800 bg-slate-950 p-3"><div className="flex flex-wrap items-start justify-between gap-3"><div><b>{guest(String(data(record)?.customerId))}</b><p className="mt-1 text-sm text-slate-400">Room {room(String(data(record)?.roomId))} · {date(data(record)?.startsAt,timeZone)} – {date(data(record)?.endsAt,timeZone)}</p></div><div className="flex flex-wrap gap-2">{children}</div></div></article>}
function Queue({title,icon,children}:{title:string;icon:React.ReactNode;children:React.ReactNode}){return <section className="rounded-2xl border border-slate-800 bg-slate-900 p-4"><h3 className="mb-3 flex items-center gap-2 font-bold">{icon}{title}</h3><div className="space-y-2">{React.Children.count(children)?children:<p className="p-5 text-center text-sm text-slate-500">No matching stays.</p>}</div></section>}
function Metric({label,value}:{label:string;value:React.ReactNode}){return <div className="rounded-2xl border border-slate-800 bg-slate-900 p-4"><div className="text-xs text-slate-500">{label}</div><div className="mt-1 truncate text-xl font-black">{value}</div></div>}
function Empty({text}:{text:string}){return <p className="rounded-xl border border-dashed border-slate-700 p-5 text-center text-sm text-slate-500">{text}</p>}
